    id TEXT NOT NULL,
    claim TEXT NOT NULL,
    citation TEXT NOT NULL,
    location TEXT NOT NULL,
    evidence TEXT NOT NULL,
    verify_by TEXT NOT NULL,
    step TEXT NOT NULL DEFAULT '',
    result TEXT NOT NULL DEFAULT '' CHECK (result IN ('', 'confirmed', 'dropped', 'undecided')),
    reason TEXT NOT NULL DEFAULT '',
    unverified INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (epic, task, generation, attempt, review, position)
);
CREATE TABLE epic_task_rung_outcomes (
    epic TEXT NOT NULL,
    task INTEGER NOT NULL,
    generation INTEGER NOT NULL,
    rung INTEGER NOT NULL,
    outcome TEXT NOT NULL CHECK (outcome IN ('failed', 'accepted', 'gap')),
    reason TEXT NOT NULL DEFAULT '',
    ended INTEGER NOT NULL,
    PRIMARY KEY (epic, task, generation, rung)
);
CREATE TABLE epic_task_rungs (
    epic TEXT NOT NULL,
    task INTEGER NOT NULL,
    generation INTEGER NOT NULL,
    rung INTEGER NOT NULL,
    kind TEXT NOT NULL CHECK (kind IN ('attempt', 'rescue', 'orchestrator', 'approach', 'gap')),
    moved_by TEXT NOT NULL DEFAULT ''
        CHECK (moved_by IN ('', 'unit', 'finding', 'fail_decision', 'cannot_meet', 'fail_task', 'send_back',
            'dependency')),
    cause TEXT NOT NULL DEFAULT '',
    gate TEXT NOT NULL DEFAULT '',
    assertion TEXT NOT NULL DEFAULT '',
    step TEXT NOT NULL DEFAULT '',
    created INTEGER NOT NULL,
    PRIMARY KEY (epic, task, generation, rung)
);
CREATE TABLE pane_sends (
    id INTEGER PRIMARY KEY,
    pane TEXT NOT NULL,
    text TEXT NOT NULL,
    client TEXT NOT NULL,
    at INTEGER NOT NULL
);
CREATE INDEX pane_sends_pane_at ON pane_sends (pane, at);
CREATE TABLE closure_verdicts (
    session_id TEXT PRIMARY KEY,
    changed INTEGER NOT NULL,
    closed INTEGER NOT NULL,
    why TEXT NOT NULL,
    at INTEGER NOT NULL
);
CREATE TABLE epic_tasks (
    epic TEXT NOT NULL,
    seq INTEGER NOT NULL,
    turn INTEGER NOT NULL,
    title TEXT NOT NULL,
    deliverable TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'open',
    gate TEXT NOT NULL DEFAULT '',
    evidence TEXT NOT NULL DEFAULT '',
    stage TEXT NOT NULL DEFAULT ''
        CHECK (stage IN ('', 'red', 'implement', 'orchestrate', 'green', 'review', 'verify', 'design')),
    base TEXT NOT NULL DEFAULT '',
    attempt INTEGER NOT NULL DEFAULT 0,
    rerun INTEGER NOT NULL DEFAULT 0,
    no_verdict INTEGER NOT NULL DEFAULT 0,
    held TEXT NOT NULL DEFAULT '' CHECK (held IN ('', 'stopped', 'parked', 'waiting', 'asked')),
    step TEXT NOT NULL DEFAULT '',
    red_run TEXT NOT NULL DEFAULT '',
    green_run TEXT NOT NULL DEFAULT '',
    revision TEXT NOT NULL DEFAULT '',
    failure TEXT NOT NULL DEFAULT '',
    review TEXT NOT NULL DEFAULT '' CHECK (review IN ('', 'unreviewed', 'reviewed')),
    refs TEXT NOT NULL DEFAULT '',
    gate_pos INTEGER NOT NULL DEFAULT 0,
    finding_pos INTEGER NOT NULL DEFAULT 0,
    batch TEXT NOT NULL DEFAULT '',
    guard TEXT NOT NULL DEFAULT '',
    needs_files TEXT NOT NULL DEFAULT '[]',
    decisions INTEGER NOT NULL DEFAULT 0,
    after_tasks TEXT NOT NULL DEFAULT '',
    question INTEGER NOT NULL DEFAULT 0,
    gate_changes TEXT NOT NULL DEFAULT '[]',
    rebriefs TEXT NOT NULL DEFAULT '',
    notes TEXT NOT NULL DEFAULT '[]',
    generation INTEGER NOT NULL DEFAULT 0,
    depends_on TEXT NOT NULL DEFAULT '',
    kind TEXT NOT NULL DEFAULT '' CHECK (kind IN ('', 'design')),
    revises INTEGER NOT NULL DEFAULT 0, split_from INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (epic, seq)
);
CREATE VIEW step_listings AS
SELECT
    steps.id,
    steps.agent,
    steps.workspace,
    steps.revision,
    steps.worktree,
    steps.read_only,
    steps.started,
    steps.checks,
    steps.doing,
    steps.verdicts,
    steps.status,
    steps.end_value,
    steps.reason,
    steps.ended,
    steps.epic,
    steps.task,
    steps.gate_name,
    steps.gate_limit,
    steps.loop_limited,
    steps.loop_limit_kind,
    steps.loop_limit_resets,
    steps.loop_stage,
    steps.loop_stage_from,
    steps.caller,
    CAST(CASE WHEN json_valid(steps.result) THEN COALESCE((
        SELECT CASE WHEN field.type = 'text' THEN field.value ELSE '' END
        FROM json_each(steps.result) AS field
        WHERE field.key = 'summary'
        ORDER BY field.id DESC
        LIMIT 1
    ), '') ELSE '' END AS TEXT) AS summary
FROM steps;
CREATE TABLE llm_accounts (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    provider TEXT NOT NULL,
    plan TEXT NOT NULL DEFAULT '',
    token TEXT NOT NULL,
    fingerprint TEXT NOT NULL,
    created INTEGER NOT NULL
);
CREATE TABLE route_registry (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    default_context TEXT NOT NULL
);
CREATE TABLE route_seats (
    id TEXT PRIMARY KEY,
    auth_mode TEXT NOT NULL CHECK (auth_mode IN ('forward', 'inject', 'sigv4')),
    upstream TEXT NOT NULL DEFAULT '',
    model TEXT NOT NULL DEFAULT '',
    api_key_env_file TEXT NOT NULL DEFAULT '',
    aws_profile TEXT NOT NULL DEFAULT '',
    aws_region TEXT NOT NULL DEFAULT '',
    model_map_env_file TEXT NOT NULL DEFAULT '',
    billing TEXT NOT NULL DEFAULT '',
    speed TEXT NOT NULL DEFAULT '',
    cache_ttl TEXT NOT NULL DEFAULT '',
    insecure INTEGER NOT NULL DEFAULT 0 CHECK (insecure IN (0, 1)),
    strip_cache_control INTEGER NOT NULL DEFAULT 0 CHECK (strip_cache_control IN (0, 1)),
    strict_structured_output INTEGER NOT NULL DEFAULT 0 CHECK (strict_structured_output IN (0, 1)),
    max_input_tokens INTEGER NOT NULL DEFAULT 0,
    strip_betas TEXT NOT NULL DEFAULT '[]'
);
CREATE TABLE route_contexts (
    id TEXT PRIMARY KEY,
    default_seat TEXT NOT NULL,
    account TEXT NOT NULL DEFAULT '',
    has_subagents INTEGER NOT NULL DEFAULT 0 CHECK (has_subagents IN (0, 1)),
    subagent_default_seat TEXT NOT NULL DEFAULT ''
);
CREATE TABLE route_bindings (
    context TEXT NOT NULL,
    scope TEXT NOT NULL CHECK (scope IN ('model', 'subagent_agent_type', 'subagent_model')),
    selector TEXT NOT NULL,
    seat TEXT NOT NULL,
    PRIMARY KEY (context, scope, selector)
);
CREATE TABLE integrate_rounds (
    epic TEXT NOT NULL,
    path TEXT NOT NULL,
    attempt INTEGER NOT NULL,
    task INTEGER NOT NULL,
    round INTEGER NOT NULL,
    step TEXT NOT NULL,
    verdict TEXT NOT NULL CHECK (verdict IN ('merged', 'clash', 'ended', 'blocked')),
    head TEXT NOT NULL DEFAULT '',
    explanation TEXT NOT NULL DEFAULT '',
    outcome TEXT NOT NULL DEFAULT '' CHECK (outcome IN ('', 'composed', 'failed', 'passed', 'skipped')),
    failure TEXT NOT NULL DEFAULT '',
    created INTEGER NOT NULL,
    PRIMARY KEY (epic, path, attempt, task, round)
);
CREATE TABLE epic_task_test_runs (
    epic TEXT NOT NULL,
    task INTEGER NOT NULL,
    generation INTEGER NOT NULL,
    attempt INTEGER NOT NULL,
    review INTEGER NOT NULL,
    position INTEGER NOT NULL,
    command TEXT NOT NULL,
    revision TEXT NOT NULL,
    step TEXT NOT NULL DEFAULT '',
    output TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (epic, task, generation, attempt, review, position)
);
CREATE TABLE designs (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    conversation TEXT NOT NULL,    -- a sessions row id; no reference to sessions
    created INTEGER NOT NULL
);
CREATE TABLE design_contracts (
    contract TEXT PRIMARY KEY REFERENCES contracts (id),
    design TEXT NOT NULL REFERENCES designs (id),
    position INTEGER NOT NULL,
    added INTEGER NOT NULL,
    UNIQUE (design, position)
);
CREATE TABLE design_edges (
    design TEXT NOT NULL REFERENCES designs (id),
    contract TEXT NOT NULL,
    after TEXT NOT NULL,
    created INTEGER NOT NULL,
    PRIMARY KEY (contract, after)
);
CREATE TABLE contract_drafts (
    id TEXT PRIMARY KEY,
    design TEXT NOT NULL,
    repository TEXT NOT NULL,
    title TEXT NOT NULL,
    body TEXT NOT NULL,
    decisions TEXT NOT NULL,
    words TEXT NOT NULL,
    writer TEXT NOT NULL,
    created INTEGER NOT NULL,
    updated INTEGER NOT NULL
);
CREATE TABLE design_steps (
    step TEXT PRIMARY KEY,
    design TEXT NOT NULL,
    kind TEXT NOT NULL CHECK (kind IN ('research', 'reproduce', 'discovery', 'closure')),
    subject TEXT NOT NULL,
    repository TEXT NOT NULL,
    revision TEXT NOT NULL,
    delta TEXT NOT NULL,
    created INTEGER NOT NULL
);
CREATE INDEX design_steps_design ON design_steps (design);
CREATE TABLE design_questions (
    design TEXT NOT NULL,
    seq INTEGER NOT NULL,
    contract TEXT NOT NULL,
    text TEXT NOT NULL,
    options TEXT NOT NULL,         -- JSON array of strings
    recommendation TEXT NOT NULL,
    asker TEXT NOT NULL,
    asked INTEGER NOT NULL,
    answer TEXT NOT NULL DEFAULT '',
    accepted INTEGER NOT NULL DEFAULT 0,
    maker TEXT NOT NULL DEFAULT '' CHECK (maker IN ('', 'owner_serve', 'owner_conversation', 'conversation')),
    quote TEXT NOT NULL DEFAULT '',
    maker_reason TEXT NOT NULL DEFAULT '',
    delegation TEXT NOT NULL DEFAULT '',
    answerer TEXT NOT NULL DEFAULT '',
    answered INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (design, seq)
);
CREATE TABLE design_dispositions (
    design TEXT NOT NULL,
    seq INTEGER NOT NULL,
    item TEXT NOT NULL,
    disposition TEXT NOT NULL CHECK (disposition IN ('adopted', 'rejected', 'deferred', 'open', 'revised_after_closure',
                                                     'accepted_as_risk')),
    reason TEXT NOT NULL,
    boundary TEXT NOT NULL,
    maker TEXT NOT NULL CHECK (maker IN ('owner_serve', 'owner_conversation', 'conversation')),
    quote TEXT NOT NULL,
    maker_reason TEXT NOT NULL,
    delegation TEXT NOT NULL,
    session TEXT NOT NULL,         -- a sessions row id; no reference to sessions
    at INTEGER NOT NULL,
    PRIMARY KEY (design, seq)
);
CREATE TABLE design_closure_skips (
    design TEXT PRIMARY KEY,
    reason TEXT NOT NULL,
    maker TEXT NOT NULL CHECK (maker IN ('owner_serve', 'owner_conversation', 'conversation')),
    quote TEXT NOT NULL,
    maker_reason TEXT NOT NULL,
    delegation TEXT NOT NULL,
    session TEXT NOT NULL,         -- a sessions row id; no reference to sessions
    at INTEGER NOT NULL
);
CREATE TABLE design_approaches (
    design TEXT NOT NULL,
    seq INTEGER NOT NULL,
    name TEXT NOT NULL,
    shape TEXT NOT NULL,
    cost TEXT NOT NULL,
    wins TEXT NOT NULL,
    loses TEXT NOT NULL,
    reconsider TEXT NOT NULL,
    research TEXT NOT NULL,        -- JSON array of step ids
    recommended INTEGER NOT NULL CHECK (recommended IN (0, 1)),
    reason TEXT NOT NULL,
    session TEXT NOT NULL,         -- a sessions row id; no reference to sessions
    at INTEGER NOT NULL,
    PRIMARY KEY (design, seq)
);
CREATE TABLE design_approach_choices (
    design TEXT NOT NULL,
    seq INTEGER NOT NULL,
    approach INTEGER NOT NULL,
    words TEXT NOT NULL,
    maker TEXT NOT NULL CHECK (maker IN ('owner_serve', 'owner_conversation', 'conversation')),
    quote TEXT NOT NULL,
    maker_reason TEXT NOT NULL,
    delegation TEXT NOT NULL,
    session TEXT NOT NULL,         -- a sessions row id; no reference to sessions
    at INTEGER NOT NULL,
    PRIMARY KEY (design, seq)
);
CREATE TABLE design_delegations (
    design TEXT NOT NULL,
    seq INTEGER NOT NULL,
    kinds TEXT NOT NULL,           -- JSON array of strings
    message TEXT NOT NULL,
    session TEXT NOT NULL,         -- a sessions row id; no reference to sessions
    at INTEGER NOT NULL,
    PRIMARY KEY (design, seq)
);
CREATE TABLE design_conversations (
    design TEXT NOT NULL,
    seq INTEGER NOT NULL,
    session TEXT NOT NULL,         -- a sessions row id; no reference to sessions
    previous TEXT NOT NULL,        -- a sessions row id, or '' for the first; no reference to sessions
    at INTEGER NOT NULL,
    PRIMARY KEY (design, seq)
);
CREATE TABLE design_log (
    design TEXT NOT NULL,
    seq INTEGER NOT NULL,
    at INTEGER NOT NULL,
    maker TEXT NOT NULL CHECK (maker IN ('owner', 'conversation', 'orreryd')),
    session TEXT NOT NULL,         -- a sessions row id; no reference to sessions
    what TEXT NOT NULL,
    ids TEXT NOT NULL,             -- JSON array of strings
    words TEXT NOT NULL,
    PRIMARY KEY (design, seq)
);
CREATE TABLE design_step_reads (
    step TEXT NOT NULL,
    contract TEXT NOT NULL,
    version INTEGER NOT NULL,      -- 0 for a draft
    PRIMARY KEY (step, contract)
);
CREATE INDEX design_step_reads_contract ON design_step_reads (contract);
CREATE TABLE contract_working (
    contract TEXT PRIMARY KEY,
    version INTEGER NOT NULL,
    body TEXT NOT NULL,
    decisions TEXT NOT NULL,
    writer TEXT NOT NULL,
    created INTEGER NOT NULL,
    updated INTEGER NOT NULL
);
CREATE TABLE contract_row_writes (
    contract TEXT NOT NULL,
    seq INTEGER NOT NULL,
    version INTEGER NOT NULL,      -- 0 for a draft
    row TEXT NOT NULL,
    action TEXT NOT NULL CHECK (action IN ('write', 'remove', 'keep', 'strike')),
    depends TEXT NOT NULL,
    words TEXT NOT NULL,
    maker TEXT NOT NULL CHECK (maker IN ('', 'owner_serve', 'owner_conversation', 'conversation')),
    quote TEXT NOT NULL,
    maker_reason TEXT NOT NULL,
    delegation TEXT NOT NULL,
    session TEXT NOT NULL,         -- a sessions row id; no reference to sessions
    at INTEGER NOT NULL,
    PRIMARY KEY (contract, seq)
);
CREATE TABLE contract_refusals (
    contract TEXT NOT NULL,
    seq INTEGER NOT NULL,
    version INTEGER NOT NULL,
    field TEXT NOT NULL,
    text TEXT NOT NULL,
    session TEXT NOT NULL,         -- a sessions row id; no reference to sessions
    at INTEGER NOT NULL,
    PRIMARY KEY (contract, seq)
);
CREATE TABLE contract_shown (
    contract TEXT NOT NULL,
    version INTEGER NOT NULL,
    row TEXT NOT NULL,
    at INTEGER NOT NULL,
    PRIMARY KEY (contract, version, row)
);
CREATE TABLE pushed_notices (
    pane TEXT NOT NULL,
    session TEXT NOT NULL,
    time INTEGER NOT NULL,
    host TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (host, pane, session)
);
CREATE INDEX notice_history_key ON notice_history (host, pane, session, epic, limit_key, alert, id);
